<script setup lang="ts">
import{onPullDownRefresh,onShow}from'@dcloudio/uni-app';import{ref}from'vue';import{afterSalesApi,type AfterSale}from'@/api/after-sales';
const rows=ref<AfterSale[]>([]),loading=ref(false),error=ref('');const labels:Record<string,string>={PENDING:'待审核',APPROVED:'已通过',REJECTED:'已驳回',PROCESSING:'处理中',COMPLETED:'已完成',CANCELLED:'已取消'};
async function load(){loading.value=true;error.value='';try{rows.value=(await afterSalesApi.list()).items??[]}catch(e){error.value=(e as{message?:string}).message??'售后记录加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function open(id:string){uni.navigateTo({url:`/pages/after-sale/detail?id=${id}`})}onShow(load);onPullDownRefresh(load);
</script>
<template><view class="page"><view class="hero"><strong>售后服务</strong><text>提交缺重、品质、破损等售后申请</text></view><view v-if="error" class="error" @click="load">{{error}}，点击重试</view><view v-for="row in rows" :key="row.id" class="card" @click="open(row.id)"><view class="head"><strong>{{row.after_sale_no}}</strong><text>{{labels[row.status]??row.status}}</text></view><text>订单：{{row.order_no||row.order_id}}</text><text>原因：{{row.reason?.name||'-'}}</text><view class="foot"><text>{{new Date(row.created_at).toLocaleString()}}</text><strong>¥{{row.refund_amount}}</strong></view></view><view v-if="!loading&&!error&&!rows.length" class="empty">暂无售后记录<br/>请从已完成订单详情发起申请</view><view v-if="loading" class="empty">正在加载…</view></view></template>
<style scoped lang="scss">.page{min-height:100vh;padding:22rpx;background:#f4f6f3}.hero{padding:34rpx;border-radius:24rpx;color:#fff;background:linear-gradient(135deg,#1b5238,#337a55)}.hero strong,.hero text,.card>text{display:block}.hero strong{font-size:34rpx}.hero text{margin-top:10rpx;color:#d4e3d9;font-size:22rpx}.card{margin-top:18rpx;padding:26rpx;border-radius:20rpx;background:#fff}.head,.foot{display:flex;align-items:center;justify-content:space-between}.head text{padding:7rpx 14rpx;border-radius:15rpx;color:#765d00;background:#fff0a8;font-size:20rpx}.card>text{margin-top:12rpx;color:#69766e;font-size:22rpx}.foot{margin-top:18rpx;padding-top:16rpx;border-top:1rpx solid #edf0ed;color:#9aa29d;font-size:19rpx}.foot strong{color:#d8583f;font-size:28rpx}.empty,.error{padding:100rpx 20rpx;color:#8b958f;text-align:center}.error{margin-top:18rpx;padding:20rpx;border-radius:16rpx;color:#a05f2b;background:#fff1dd}</style>
